function validate([root, target, k]) {
  if (root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  // Walk the level-order array with the value range each position allows.
  const values = [];
  const bounds = [[-Infinity, Infinity]];
  let next = 0;
  for (let i = 0; i < bounds.length && next < root.length; i++) {
    const value = root[next++];
    if (value === null) continue;
    const [low, high] = bounds[i];
    if (value <= low || value >= high) return 'root must be a valid binary search tree with distinct values.';
    values.push(value);
    bounds.push([low, value], [value, high]);
  }
  const n = values.length;
  if (n > 10000) return 'The tree has at most 10^4 nodes.';
  if (values.some(v => v < 0 || v > 1000000000)) return 'Node values are between 0 and 10^9.';
  if (target < -1000000000 || target > 1000000000) return 'target is between -10^9 and 10^9.';
  if (k < 1 || k > n) return 'k is between 1 and the number of nodes.';
  const gaps = values.map(v => Math.abs(v - target)).sort((a, b) => a - b);
  if (k < n && gaps[k - 1] === gaps[k]) return 'The k closest values must be unique; this target creates a tie.';
  return null;
}

