function closestKValues(root, target, k) {
  // Gather every value, sort them all by distance to target, keep the first k.
  const values = [];
  const queue = [root];
  for (let i = 0; i < queue.length; i++) {
    values.push(queue[i].val);
    if (queue[i].left) queue.push(queue[i].left);
    if (queue[i].right) queue.push(queue[i].right);
  }
  values.sort((a, b) => Math.abs(a - target) - Math.abs(b - target));
  return values.slice(0, k);
}

