function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  for (;;) {
    const n = large ? 900 + pick(99) : 1 + pick(9);
    const span = large || rand() < 0.25 ? 1000000000 : 30;
    const used = new Set();
    while (used.size < n) used.add(pick(span + 1));
    const order = [...used];
    const shape = rand();
    // Sorted insertion makes a chain; otherwise a random order gives a bushy tree.
    if (!large && shape < 0.2) order.sort((a, b) => a - b);
    else if (!large && shape < 0.35) order.sort((a, b) => b - a);
    let tree = null;
    for (const value of order) {
      const fresh = { val: value, left: null, right: null };
      if (tree === null) { tree = fresh; continue; }
      for (let node = tree; ;) {
        const side = value < node.val ? 'left' : 'right';
        if (node[side] === null) { node[side] = fresh; break; }
        node = node[side];
      }
    }
    const root = [];
    const queue = [tree];
    for (let i = 0; i < queue.length; i++) {
      root.push(queue[i] ? queue[i].val : null);
      if (queue[i]) queue.push(queue[i].left, queue[i].right);
    }
    while (root[root.length - 1] === null) root.pop();
    // Targets sit near a stored value, sometimes far outside the range, with a few decimals.
    const base = rand() < 0.15 ? (rand() < 0.5 ? -1 : 1) * pick(span + 1) : order[pick(n)];
    const offset = span > 30 ? Math.round((rand() - 0.5) * 2000000000) / 1000000 : pick(9) / 4 - 1;
    const target = Math.max(-1000000000, Math.min(1000000000, base + offset));
    const k = 1 + pick(n);
    const gaps = order.map(v => Math.abs(v - target)).sort((a, b) => a - b);
    if (k === n || gaps[k - 1] !== gaps[k]) return [root, target, k];
  }
}
